import './style.css';
import './override.css';
import './admin.css';
const api=import.meta.env.VITE_API_URL||'http://localhost:5293/api';
let s=JSON.parse(sessionStorage.getItem('session')||'null'),view='dashboard';
const app=document.querySelector('#app'),type=['Tài liệu PDF','Tài liệu Word','Bài trình chiếu','Video bài giảng','Gói SCORM','Trang HTML','Tệp nén ZIP'];
// Ghi trực tiếp vào DOM để không bị CSS mặc định của Vite/tiện ích trình duyệt giới hạn vùng ứng dụng.
document.documentElement.style.setProperty('background','#f4f7fb','important');
document.documentElement.style.setProperty('width','100%','important');
document.body.style.setProperty('background','#f4f7fb','important');
document.body.style.setProperty('width','100%','important');
document.body.style.setProperty('overflow-x','hidden','important');
app.style.setProperty('max-width','none','important');
app.style.setProperty('width','100%','important');
app.style.setProperty('min-height','100vh','important');
app.style.setProperty('margin','0','important');
app.style.setProperty('padding','0','important');
const roleName={Admin:'Quản trị viên',CCD:'Chuyên viên CCD',Lecturer:'Giảng viên'};
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
async function req(path,o={}){const form=o.body instanceof FormData,controller=new AbortController(),timer=setTimeout(()=>controller.abort(),12000);try{const r=await fetch(api+path,{...o,signal:controller.signal,headers:{...(s?{Authorization:'Bearer '+s.accessToken}:{}),...(form?{}:{'Content-Type':'application/json'}),...o.headers}}),raw=await r.text(),d=raw?(()=>{try{return JSON.parse(raw)}catch{return raw}})():null;if(!r.ok){const message=typeof d==='string'?d:(d?.message||d?.title||d?.detail||raw||`Yêu cầu không thành công (mã ${r.status}).`);throw Error(message)}return d}catch(e){if(e.name==='AbortError')throw Error('Không thể kết nối tới máy chủ trong 12 giây. Hãy kiểm tra backend đang chạy tại http://localhost:5293.');if(e instanceof TypeError)throw Error('Không thể kết nối tới máy chủ. Hãy chạy backend và kiểm tra địa chỉ http://localhost:5293/swagger.');throw e}finally{clearTimeout(timer)}}
function shell(body){const admin=s.role==='Admin',items=admin?[['dashboard','Tổng quan'],['catalog','Danh mục đào tạo'],['admin-materials','Quản lý học liệu'],['users','Quản lý tài khoản'],['reports','Báo cáo']]:[['dashboard','Tổng quan'],['submit','Nộp học liệu'],['materials','Học liệu và báo cáo'],...(s.role==='CCD'?[['reports','Báo cáo']]:[])];app.innerHTML=`<header><a class="brand" href="#"><i>◆</i><span>Hệ thống học liệu số<small>KIỂM THỬ & NGHIỆM THU THEO OBE</small></span></a><nav>${items.map(x=>`<button data-v="${x[0]}" class="${view===x[0]?'active':''}">${x[1]}</button>`).join('')}</nav><div class="user"><span><b>${esc(s.fullName)}</b><small>${roleName[s.role]||esc(s.role)}</small></span><button id="out" title="Đăng xuất">Đăng xuất</button></div></header><main><div id="note"></div>${body}</main>`;document.querySelectorAll('[data-v]').forEach(x=>x.onclick=()=>{view=x.dataset.v;render()});document.querySelector('#out').onclick=()=>{sessionStorage.clear();s=null;login()}}
function note(x,bad=false){document.querySelector('#note').innerHTML=`<p class="${bad?'error':'success'}">${esc(x)}</p>`}
function login(msg=''){app.innerHTML=`<main class="login" style="position:fixed;inset:0;width:100vw;height:100vh;margin:0"><aside class="login-intro"><div class="intro-inner"><div class="intro-logo">◆</div><p class="intro-eyebrow">TRUNG TÂM HỌC LIỆU SỐ</p><h2>Kiểm thử minh bạch.<br>Nghiệm thu có căn cứ.</h2><p>Không gian quản lý tập trung cho học liệu số theo chuẩn đầu ra OBE.</p><div class="intro-steps"><span><i>01</i> Nộp học liệu và phân loại</span><span><i>02</i> AI đánh giá và gợi ý khắc phục</span><span><i>03</i> CCD kiểm thử, phản hồi, nghiệm thu</span></div><small>HỆ THỐNG QUẢN LÝ CHẤT LƯỢNG HỌC LIỆU</small></div></aside><section><div class="login-mark">◆</div><p class="eyebrow">ĐĂNG NHẬP HỆ THỐNG</p><h1>Chào mừng trở lại</h1><p>Đăng nhập bằng tài khoản do Quản trị viên cấp.</p><form id="login"><label>Tên đăng nhập<input name="username" required autofocus autocomplete="username" placeholder="Nhập tên đăng nhập"></label><label>Mật khẩu<input type="password" name="password" required autocomplete="current-password" placeholder="Nhập mật khẩu"></label><button type="submit">Đăng nhập hệ thống <span>→</span></button><small class="error">${esc(msg)}</small></form><p class="login-help">Quên mật khẩu? Liên hệ Quản trị viên để được đặt lại.</p></section></main>`;document.querySelector('#login').onsubmit=async e=>{e.preventDefault();const b=e.submitter;b.disabled=true;b.textContent='Đang xác thực…';try{s=await req('/auth/login',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});sessionStorage.setItem('session',JSON.stringify(s));await render()}catch(e){login(e.message)}finally{if(document.contains(b)){b.disabled=false;b.innerHTML='Đăng nhập hệ thống <span>→</span>'}}}}
async function dashboard(){const [m,t]=await Promise.all([req('/learning-materials'),req('/test-requests')]);shell(`<h1>Tổng quan</h1><p>Dữ liệu lấy trực tiếp từ cơ sở dữ liệu.</p><section class="stats"><article><b>${m.length}</b><span>Học liệu</span></article><article><b>${t.length}</b><span>Lượt kiểm thử</span></article><article><b>${m.filter(x=>x.status===5).length}</b><span>Cần chỉnh sửa</span></article><article><b>${m.filter(x=>x.status===6).length}</b><span>Đã nghiệm thu</span></article></section>`)}
async function submit(){const c=await req('/courses');shell(`<h1>Nộp học liệu</h1><section class="card"><form id="submit"><label>Mã học liệu<input name="code" required placeholder="HL-CNTT-001"></label><label>Tên học liệu<input name="title" required></label><label>Học phần<select name="courseId" required><option value="">Chọn học phần</option>${c.map(x=>`<option value="${x.id}">${esc(x.departmentName)}${x.majorName?' · '+esc(x.majorName):''} · ${esc(x.code)} – ${esc(x.name)}</option>`).join('')}</select></label><label>Loại<select name="materialType">${type.map((x,i)=>`<option value="${i}">${x}</option>`).join('')}</select></label><label class="wide">Mô tả, CLO, hoạt động, câu hỏi<textarea name="description"></textarea></label><label class="wide">Tệp học liệu<input name="file" required type="file" accept=".pdf,.doc,.docx,.ppt,.pptx,.mp4,.zip,.html"></label><button>Nộp và chạy kiểm thử</button></form></section>`);document.querySelector('#submit').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),b=e.submitter;b.disabled=true;try{const m=await req('/learning-materials',{method:'POST',body:JSON.stringify({code:f.get('code'),courseId:f.get('courseId'),title:f.get('title'),description:f.get('description')||null,materialType:+f.get('materialType')})}),up=new FormData();up.append('learningMaterialId',m.id);up.append('file',f.get('file'));up.append('remark',f.get('description')||'');const v=await req('/material-versions/upload',{method:'POST',body:up});await req('/auto-tests',{method:'POST',body:JSON.stringify({materialVersionId:v.id})});note('Đã lưu học liệu, tải phiên bản và tạo lượt kiểm thử tự động.')}catch(x){note(x.message,true)}finally{b.disabled=false}}}
async function materials(){const [m,c]=await Promise.all([req('/learning-materials'),req('/courses')]),deps=[...new Map(c.map(x=>[x.departmentId,x.departmentName])).entries()];shell(`<h1>Học liệu</h1><section class="filters"><select id="dep"><option value="">Tất cả khoa</option>${deps.map(x=>`<option value="${x[0]}">${esc(x[1])}</option>`).join('')}</select><select id="major"><option value="">Tất cả ngành</option></select></section><section class="card"><table><thead><tr><th>Mã</th><th>Học liệu</th><th>Khoa / Ngành</th><th>Loại</th><th>Trạng thái</th></tr></thead><tbody id="rows"></tbody></table></section>`);const d=document.querySelector('#dep'),g=document.querySelector('#major'),r=document.querySelector('#rows');function paint(){r.innerHTML=m.filter(x=>{const z=c.find(y=>y.id===x.courseId);return(!d.value||z?.departmentId===d.value)&&(!g.value||z?.majorId===g.value)}).map(x=>{const z=c.find(y=>y.id===x.courseId);return`<tr><td>${esc(x.code)}</td><td><b>${esc(x.title)}</b><br><small>${esc(x.courseName)}</small></td><td>${esc(z?.departmentName||'')}<br><small>${esc(z?.majorName||'Chưa gắn ngành')}</small></td><td>${type[x.materialType]||''}</td><td>${['Nháp','Đã tải','Đang xử lý','Đã kiểm thử','Chờ duyệt','Cần sửa','Đã nghiệm thu'][x.status]||''}</td></tr>`}).join('')||'<tr><td colspan="5">Không có dữ liệu.</td></tr>'}d.onchange=()=>{g.innerHTML='<option value="">Tất cả ngành</option>'+[...new Map(c.filter(x=>x.departmentId===d.value&&x.majorId).map(x=>[x.majorId,x.majorName])).entries()].map(x=>`<option value="${x[0]}">${esc(x[1])}</option>`).join('');paint()};g.onchange=paint;paint()}
async function tests(){const x=await req('/test-requests');shell(`<h1>Kiểm thử và nghiệm thu</h1><section class="card"><table><thead><tr><th>Học liệu</th><th>Phiên bản</th><th>Người nộp</th><th>Tester</th><th>Trạng thái</th><th>Kết luận</th></tr></thead><tbody>${x.map(t=>`<tr><td>${esc(t.learningMaterialTitle)}</td><td>v${t.versionNumber}</td><td>${esc(t.uploadedByName)}</td><td>${esc(t.testerName||'AI tự động')}</td><td>${esc(t.status)}</td><td>${esc(t.conclusion||'')}</td></tr>`).join('')||'<tr><td colspan="6">Chưa có lượt kiểm thử.</td></tr>'}</tbody></table></section>`)}
async function users(){const [u,d]=await Promise.all([req('/users'),req('/departments')]);shell(`<h1>Cấp tài khoản</h1><section class="card"><form id="user"><label>Tên đăng nhập<input name="username" required></label><label>Họ tên<input name="fullName" required></label><label>Email<input name="email" type="email" required></label><label>Mật khẩu ban đầu<input name="password" type="password" minlength="6" required></label><label>Vai trò<select name="role"><option value="Lecturer">Giảng viên</option><option value="CCD">CCD</option></select></label><label>Khoa<select name="departmentId">${d.map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('')}</select></label><button>Cấp tài khoản</button></form></section><section class="card"><table><thead><tr><th>Họ tên</th><th>Đăng nhập</th><th>Vai trò</th><th>Khoa</th></tr></thead><tbody>${u.map(x=>`<tr><td>${esc(x.fullName)}</td><td>${esc(x.username)}</td><td>${esc(x.role)}</td><td>${esc(x.department)}</td></tr>`).join('')}</tbody></table></section>`);document.querySelector('#user').onsubmit=async e=>{e.preventDefault();try{await req('/users',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});users()}catch(x){note(x.message,true)}}}
async function catalog(){const [d,g,c]=await Promise.all([req('/departments'),req('/majors'),req('/courses')]);shell(`<h1>Danh mục Khoa · Ngành · Học phần</h1><div class="columns"><section class="card"><h2>Thêm ngành</h2><form id="major"><label>Khoa<select name="departmentId">${d.map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('')}</select></label><label>Mã ngành<input name="code" required></label><label>Tên ngành<input name="name" required></label><button>Lưu ngành</button></form><ul>${g.map(x=>`<li>${esc(x.name)}</li>`).join('')||'<li>Chưa có ngành</li>'}</ul></section><section class="card"><h2>Thêm học phần</h2><form id="course"><label>Khoa<select id="cd" name="departmentId">${d.map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('')}</select></label><label>Ngành<select id="cm" name="majorId"><option value="">Tất cả ngành / chưa gắn</option></select></label><label>Mã<input name="code" required></label><label>Tên học phần<input name="name" required></label><label>Tín chỉ<input name="credits" value="3" type="number"></label><label>Học kỳ<input name="semester" value="1"></label><label>Năm học<input name="academicYear" value="2026-2027"></label><label class="wide">Mô tả<textarea name="description"></textarea></label><button>Lưu học phần</button></form><p>Hiện có ${c.length} học phần.</p></section></div>`);const cd=document.querySelector('#cd'),cm=document.querySelector('#cm'),fill=()=>cm.innerHTML='<option value="">Tất cả ngành / chưa gắn</option>'+g.filter(x=>x.departmentId===cd.value).map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('');cd.onchange=fill;fill();document.querySelector('#major').onsubmit=async e=>{e.preventDefault();try{await req('/majors',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});catalog()}catch(x){note(x.message,true)}};document.querySelector('#course').onsubmit=async e=>{e.preventDefault();const z=Object.fromEntries(new FormData(e.target));z.majorId=z.majorId||null;z.credits=+z.credits;try{await req('/courses',{method:'POST',body:JSON.stringify(z)});catalog()}catch(x){note(x.message,true)}}}
async function accountAdmin(){const [u,d,summary]=await Promise.all([req('/users'),req('/departments'),req('/users/summary')]);shell(`<h1>Quản lý tài khoản</h1><section class="stats"><article><b>${summary.total}</b><span>Tổng tài khoản</span></article><article><b>${summary.active}</b><span>Đang hoạt động</span></article><article><b>${summary.locked}</b><span>Đã khóa</span></article><article><b>${summary.ccd+summary.lecturers}</b><span>CCD và giảng viên</span></article></section><section class="card"><h2>Cấp tài khoản mới</h2><form id="user"><label>Tên đăng nhập<input name="username" required></label><label>Họ tên<input name="fullName" required></label><label>Email<input name="email" type="email" required></label><label>Mật khẩu ban đầu<input name="password" type="password" minlength="6" required></label><label>Vai trò<select name="role"><option value="Lecturer">Giảng viên</option><option value="CCD">Chuyên viên CCD</option></select></label><label>Khoa<select name="departmentId">${d.map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('')}</select></label><button>Cấp tài khoản</button></form></section><section class="card"><h2>Tài khoản đã cấp</h2><table><thead><tr><th>Họ tên</th><th>Đăng nhập</th><th>Vai trò</th><th>Khoa</th><th>Trạng thái</th><th></th></tr></thead><tbody>${u.map(x=>`<tr><td>${esc(x.fullName)}</td><td>${esc(x.username)}</td><td>${esc(roleName[x.role]||x.role)}</td><td>${esc(x.department)}</td><td>${x.status===2?'Đã khóa':'Hoạt động'}</td><td>${x.role==='Admin'?'':`<button class="mini" data-lock="${x.id}" data-locked="${x.status===2}">${x.status===2?'Mở khóa':'Khóa'}</button> <button class="mini danger" data-delete="${x.id}">Xóa</button>`}</td></tr>`).join('')}</tbody></table></section>`);document.querySelector('#user').onsubmit=async e=>{e.preventDefault();try{await req('/users',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});accountAdmin()}catch(x){note(x.message,true)}};document.querySelectorAll('[data-lock]').forEach(b=>b.onclick=async()=>{try{await req('/users/'+b.dataset.lock+'/lock?locked='+(!JSON.parse(b.dataset.locked)),{method:'PUT'});accountAdmin()}catch(x){note(x.message,true)}});document.querySelectorAll('[data-delete]').forEach(b=>b.onclick=async()=>{if(!confirm('Xóa tài khoản này?'))return;try{await req('/users/'+b.dataset.delete,{method:'DELETE'});accountAdmin()}catch(x){note(x.message,true)}})}
async function adminMaterials(){const [m,c]=await Promise.all([req('/learning-materials'),req('/courses')]);shell(`<h1>Quản lý học liệu</h1><p>Admin có thể cập nhật thông tin hoặc xóa học liệu. Khi xóa, các phiên bản liên quan cũng được xóa.</p><section class="card"><table><thead><tr><th>Mã</th><th>Học liệu</th><th>Người nộp</th><th>Học phần</th><th></th></tr></thead><tbody>${m.map(x=>`<tr><td>${esc(x.code)}</td><td><b>${esc(x.title)}</b><br><small>${esc(x.description||'')}</small></td><td>${esc(x.ownerName)}</td><td>${esc(x.courseName)}</td><td><button class="mini" data-edit="${x.id}">Sửa</button> <button class="mini danger" data-remove="${x.id}">Xóa</button></td></tr>`).join('')||'<tr><td colspan="5">Chưa có học liệu.</td></tr>'}</tbody></table></section>`);document.querySelectorAll('[data-remove]').forEach(b=>b.onclick=async()=>{if(!confirm('Xóa học liệu này cùng các phiên bản liên quan?'))return;try{await req('/learning-materials/'+b.dataset.remove,{method:'DELETE'});adminMaterials()}catch(x){note(x.message,true)}});document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>{const x=m.find(z=>z.id===b.dataset.edit);shell(`<h1>Cập nhật học liệu</h1><section class="card"><form id="edit-material"><label>Học phần<select name="courseId">${c.map(z=>`<option value="${z.id}" ${z.id===x.courseId?'selected':''}>${esc(z.name)}</option>`).join('')}</select></label><label>Loại<select name="materialType">${type.map((z,i)=>`<option value="${i}" ${i===x.materialType?'selected':''}>${z}</option>`).join('')}</select></label><label class="wide">Tên học liệu<input name="title" value="${esc(x.title)}" required></label><label class="wide">Mô tả<textarea name="description">${esc(x.description||'')}</textarea></label><button>Lưu thay đổi</button></form></section>`);document.querySelector('#edit-material').onsubmit=async e=>{e.preventDefault();const z=Object.fromEntries(new FormData(e.target));z.materialType=+z.materialType;try{await req('/learning-materials/'+x.id,{method:'PUT',body:JSON.stringify(z)});view='admin-materials';render()}catch(err){note(err.message,true)}}})}
async function reports(){const [r,logs]=await Promise.all([req('/reports/overview'),req('/reports/audit-logs')]);shell(`<h1>Báo cáo chất lượng</h1><p>Số liệu tổng hợp trực tiếp từ cơ sở dữ liệu hiện tại.</p><section class="stats"><article><b>${r.materials}</b><span>Tổng học liệu</span></article><article><b>${r.pendingApproval}</b><span>Chờ nghiệm thu</span></article><article><b>${r.needRevision}</b><span>Cần chỉnh sửa</span></article><article><b>${r.approved}</b><span>Đã nghiệm thu</span></article></section><section class="card"><h2>Chất lượng học liệu theo khoa</h2><table><thead><tr><th>Khoa</th><th>Tổng học liệu</th><th>Cần chỉnh sửa</th><th>Đã nghiệm thu</th></tr></thead><tbody>${r.byDepartment.map(x=>`<tr><td>${esc(x.department)}</td><td>${x.total}</td><td>${x.needRevision}</td><td>${x.approved}</td></tr>`).join('')||'<tr><td colspan="4">Chưa có học liệu.</td></tr>'}</tbody></table></section><section class="card"><h2>Nhật ký hoạt động gần đây</h2><table><thead><tr><th>Thời gian</th><th>Người thực hiện</th><th>Hoạt động</th><th>Chi tiết</th></tr></thead><tbody>${logs.map(x=>`<tr><td>${new Date(x.createdAt).toLocaleString('vi-VN')}</td><td>${esc(x.user)}</td><td>${esc(x.action)}</td><td>${esc(x.description)}</td></tr>`).join('')||'<tr><td colspan="4">Chưa có nhật ký.</td></tr>'}</tbody></table></section>`)}
async function render(){if(!s)return login();try{if(view==='submit')return submit();if(view==='materials')return materials();if(view==='tests')return tests();if(view==='users')return accountAdmin();if(view==='admin-materials')return adminMaterials();if(view==='catalog')return catalog();if(view==='reports')return reports();return dashboard()}catch(e){shell(`<h1>Không thể tải dữ liệu</h1><section class="card"><p class="error">${esc(e.message)}</p><p>Hãy kiểm tra backend đã khởi động và database đã được cập nhật migration.</p><button id="retry">Thử lại</button></section>`);document.querySelector('#retry').onclick=()=>render()}}
const renderCatalogBase=catalog;
catalog=async()=>{await renderCatalogBase();const anchor=document.querySelector('main h1');if(!anchor)return;anchor.insertAdjacentHTML('afterend','<section class="card catalog-add"><h2>Thêm khoa / đơn vị</h2><form id="department-form"><label>Mã khoa<input name="code" required placeholder="VD: CNTT"></label><label>Tên khoa / đơn vị<input name="name" required placeholder="VD: Khoa Công nghệ thông tin"></label><label class="wide">Mô tả<input name="description" placeholder="Không bắt buộc"></label><button>Thêm khoa</button></form></section>');document.querySelector('#department-form').onsubmit=async e=>{e.preventDefault();try{await req('/departments',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});await catalog()}catch(err){note(err.message,true)}}};
render();

/* Màn danh mục theo kiểu quản trị: biểu mẫu gọn, bảng dữ liệu và phân trang thật ở phía trình duyệt. */
catalog=async()=>{
  const [departments,majors,courses]=await Promise.all([req('/departments'),req('/majors'),req('/courses')]);
  let coursePage=1;
  const pageSize=10;
  const departmentOptions=departments.map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('');
  shell(`<section class="page-title"><div><p class="breadcrumb">QUẢN TRỊ HỆ THỐNG / DANH MỤC</p><h1>Danh mục đào tạo</h1><p>Quản lý khoa, ngành và học phần trên cùng một không gian làm việc.</p></div></section>
  <section class="catalog-summary"><article><span>Khoa / đơn vị</span><b>${departments.length}</b></article><article><span>Ngành đào tạo</span><b>${majors.length}</b></article><article><span>Học phần</span><b>${courses.length}</b></article></section>
  <section class="catalog-create"><div class="create-heading"><div><h2>Thêm danh mục</h2><p>Nhập thông tin tối thiểu. Dữ liệu được lưu trực tiếp vào hệ thống.</p></div></div><div class="catalog-forms">
    <form id="department-form" class="catalog-form"><h3>Khoa / đơn vị</h3><label>Mã khoa<input name="code" required placeholder="VD: CNTT"></label><label>Tên khoa / đơn vị<input name="name" required placeholder="VD: Khoa Công nghệ thông tin"></label><button>Thêm khoa</button></form>
    <details class="course-create"><summary><span><b>Thêm học phần</b><small>Chọn khoa trước, sau đó hệ thống chỉ hiển thị các ngành thuộc khoa đã chọn</small></span><i>+</i></summary><form id="course-form"><label>Khoa<select id="course-department" name="departmentId" required>${departmentOptions}</select></label><label>Ngành<select id="course-major" name="majorId" required><option value="">Chọn khoa trước</option></select></label><label>Mã học phần<input name="code" required placeholder="VD: IT101"></label><label>Tên học phần<input name="name" required></label><label>Tín chỉ<input name="credits" value="3" type="number" min="1" required></label><label>Học kỳ<input name="semester" value="1" required></label><label>Năm học<input name="academicYear" value="2026-2027" required></label><button>Lưu học phần</button></form></details>
  </div></section>
  <section class="data-panel"><div class="data-panel-head"><div><h2>Danh sách học phần</h2><p id="course-count"></p></div><div class="data-tools"><input id="course-search" placeholder="Tìm mã hoặc tên học phần"></div></div><div class="table-wrap"><table><thead><tr><th>Mã HP</th><th>Học phần</th><th>Khoa / ngành</th><th>Tín chỉ</th><th>Học kỳ</th></tr></thead><tbody id="course-rows"></tbody></table></div><div id="course-pager"></div></section>`);

  const pagination=(id,total,page,setPage)=>{const pages=Math.max(1,Math.ceil(total/pageSize));const current=Math.min(page,pages);const root=document.querySelector(id);root.innerHTML=`<div class="pager"><span>Hiển thị ${total?((current-1)*pageSize+1):0}–${Math.min(current*pageSize,total)} / ${total} bản ghi</span><div><button class="page-btn" data-page="${current-1}" ${current===1?'disabled':''}>‹ Trước</button>${Array.from({length:pages},(_,i)=>i+1).filter(x=>x===1||x===pages||Math.abs(x-current)<=1).map((x,i,a)=>`${i&&x-a[i-1]>1?'<em>…</em>':''}<button class="page-btn ${x===current?'current':''}" data-page="${x}">${x}</button>`).join('')}<button class="page-btn" data-page="${current+1}" ${current===pages?'disabled':''}>Sau ›</button></div></div>`;root.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>setPage(+b.dataset.page));};
  const paintCourses=()=>{const q=document.querySelector('#course-search').value.trim().toLowerCase(),rows=courses.filter(x=>!q||`${x.code} ${x.name}`.toLowerCase().includes(q));coursePage=Math.min(coursePage,Math.max(1,Math.ceil(rows.length/pageSize)));document.querySelector('#course-count').textContent=`${rows.length} học phần phù hợp`;document.querySelector('#course-rows').innerHTML=rows.slice((coursePage-1)*pageSize,coursePage*pageSize).map(x=>`<tr><td><span class="code">${esc(x.code)}</span></td><td><b>${esc(x.name)}</b></td><td>${esc(x.departmentName||'')}<small>${esc(x.majorName||'Chưa gắn ngành')}</small></td><td>${x.credits}</td><td>${esc(x.semester)}</td></tr>`).join('')||'<tr><td colspan="5" class="empty">Chưa có học phần phù hợp.</td></tr>';pagination('#course-pager',rows.length,coursePage,p=>{coursePage=p;paintCourses()});};
  const fillCourseMajors=()=>{const selected=document.querySelector('#course-department').value,choices=majors.filter(x=>x.departmentId===selected);document.querySelector('#course-major').innerHTML='<option value="">Chọn ngành</option>'+choices.map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('');};
  document.querySelector('#course-search').oninput=()=>{coursePage=1;paintCourses()};document.querySelector('#course-department').onchange=fillCourseMajors;fillCourseMajors();paintCourses();
  document.querySelector('#department-form').onsubmit=async e=>{e.preventDefault();try{await req('/departments',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});await catalog()}catch(err){note(err.message,true)}};
  document.querySelector('#course-form').onsubmit=async e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.target));data.majorId=data.majorId||null;data.credits=+data.credits;try{await req('/courses',{method:'POST',body:JSON.stringify(data)});await catalog()}catch(err){note(err.message,true)}};
};

const tablePager=(root,total,page,onChange)=>{const size=10,pages=Math.max(1,Math.ceil(total/size)),current=Math.min(page,pages);root.innerHTML=`<div class="pager"><span>Hiển thị ${total?(current-1)*size+1:0}–${Math.min(current*size,total)} / ${total} bản ghi</span><div><button class="page-btn" data-p="${current-1}" ${current===1?'disabled':''}>‹ Trước</button>${Array.from({length:pages},(_,i)=>i+1).filter(x=>x===1||x===pages||Math.abs(x-current)<=1).map((x,i,a)=>`${i&&x-a[i-1]>1?'<em>…</em>':''}<button class="page-btn ${x===current?'current':''}" data-p="${x}">${x}</button>`).join('')}<button class="page-btn" data-p="${current+1}" ${current===pages?'disabled':''}>Sau ›</button></div></div>`;root.querySelectorAll('[data-p]').forEach(x=>x.onclick=()=>onChange(+x.dataset.p));};

accountAdmin=async()=>{
  const [users,deps,summary]=await Promise.all([req('/users'),req('/departments'),req('/users/summary')]);let page=1;const options=deps.map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('');
  shell(`<section class="page-title"><div><p class="breadcrumb">QUẢN TRỊ HỆ THỐNG / TÀI KHOẢN</p><h1>Quản lý tài khoản</h1><p>Quản lý quyền truy cập của giảng viên và chuyên viên CCD.</p></div></section><section class="stats"><article><b>${summary.total}</b><span>Tổng tài khoản</span></article><article><b>${summary.active}</b><span>Đang hoạt động</span></article><article><b>${summary.locked}</b><span>Đã khóa</span></article><article><b>${summary.ccd+summary.lecturers}</b><span>CCD và giảng viên</span></article></section><details class="course-create account-create"><summary><span><b>Cấp tài khoản mới</b><small>Tạo tài khoản cho giảng viên hoặc chuyên viên CCD</small></span><i>+</i></summary><form id="user-form"><label>Tên đăng nhập<input name="username" required></label><label>Họ tên<input name="fullName" required></label><label>Email<input name="email" type="email" required></label><label>Mật khẩu ban đầu<input name="password" type="password" minlength="6" required></label><label>Vai trò<select name="role"><option value="Lecturer">Giảng viên</option><option value="CCD">Chuyên viên CCD</option></select></label><label>Khoa<select name="departmentId" required>${options}</select></label><button>Cấp tài khoản</button></form></details><section class="data-panel"><div class="data-panel-head"><div><h2>Tài khoản đã cấp</h2><p id="user-count"></p></div><div class="data-tools"><input id="user-search" placeholder="Tìm tên, tài khoản, email"></div></div><div class="table-wrap"><table><thead><tr><th>Họ tên</th><th>Tên đăng nhập</th><th>Vai trò</th><th>Khoa</th><th>Trạng thái</th><th></th></tr></thead><tbody id="user-rows"></tbody></table></div><div id="user-pager"></div></section>`);
  const paint=()=>{const q=document.querySelector('#user-search').value.trim().toLowerCase(),rows=users.filter(x=>!q||`${x.fullName} ${x.username} ${x.email||''}`.toLowerCase().includes(q)),size=10;page=Math.min(page,Math.max(1,Math.ceil(rows.length/size)));document.querySelector('#user-count').textContent=`${rows.length} tài khoản phù hợp`;document.querySelector('#user-rows').innerHTML=rows.slice((page-1)*size,page*size).map(x=>`<tr><td><b>${esc(x.fullName)}</b><small>${esc(x.email||'')}</small></td><td>${esc(x.username)}</td><td>${esc(roleName[x.role]||x.role)}</td><td>${esc(x.department||'')}</td><td><span class="status ${x.status===2?'locked':'active'}">${x.status===2?'Đã khóa':'Hoạt động'}</span></td><td>${x.role==='Admin'?'':`<button class="mini" data-lock="${x.id}" data-locked="${x.status===2}">${x.status===2?'Mở khóa':'Khóa'}</button> <button class="mini danger" data-delete="${x.id}">Xóa</button>`}</td></tr>`).join('')||'<tr><td class="empty" colspan="6">Không có tài khoản phù hợp.</td></tr>';tablePager(document.querySelector('#user-pager'),rows.length,page,p=>{page=p;paint()});document.querySelectorAll('[data-lock]').forEach(b=>b.onclick=async()=>{try{await req(`/users/${b.dataset.lock}/lock?locked=${!JSON.parse(b.dataset.locked)}`,{method:'PUT'});accountAdmin()}catch(e){note(e.message,true)}});document.querySelectorAll('[data-delete]').forEach(b=>b.onclick=async()=>{if(!confirm('Xóa tài khoản này?'))return;try{await req(`/users/${b.dataset.delete}`,{method:'DELETE'});accountAdmin()}catch(e){note(e.message,true)}})};document.querySelector('#user-search').oninput=()=>{page=1;paint()};paint();document.querySelector('#user-form').onsubmit=async e=>{e.preventDefault();try{await req('/users',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});accountAdmin()}catch(err){note(err.message,true)}};
};

adminMaterials=async()=>{
  const [materials,courses]=await Promise.all([req('/learning-materials'),req('/courses')]);let page=1;
  shell(`<section class="page-title"><div><p class="breadcrumb">QUẢN TRỊ HỆ THỐNG / HỌC LIỆU</p><h1>Quản lý học liệu</h1><p>Cập nhật hoặc xóa học liệu và các phiên bản liên quan.</p></div></section><section class="data-panel"><div class="data-panel-head"><div><h2>Danh sách học liệu</h2><p id="material-count"></p></div><div class="data-tools"><input id="material-search" placeholder="Tìm mã, tên hoặc người nộp"></div></div><div class="table-wrap"><table><thead><tr><th>Mã</th><th>Học liệu</th><th>Người nộp</th><th>Học phần</th><th></th></tr></thead><tbody id="material-rows"></tbody></table></div><div id="material-pager"></div></section>`);
  const paint=()=>{const q=document.querySelector('#material-search').value.trim().toLowerCase(),rows=materials.filter(x=>!q||`${x.code} ${x.title} ${x.ownerName}`.toLowerCase().includes(q)),size=10;page=Math.min(page,Math.max(1,Math.ceil(rows.length/size)));document.querySelector('#material-count').textContent=`${rows.length} học liệu phù hợp`;document.querySelector('#material-rows').innerHTML=rows.slice((page-1)*size,page*size).map(x=>`<tr><td><span class="code">${esc(x.code)}</span></td><td><b>${esc(x.title)}</b><small>${esc(x.description||'Không có mô tả')}</small></td><td>${esc(x.ownerName)}</td><td>${esc(x.courseName)}</td><td><button class="mini" data-edit="${x.id}">Sửa</button> <button class="mini danger" data-remove="${x.id}">Xóa</button></td></tr>`).join('')||'<tr><td colspan="5" class="empty">Không có học liệu phù hợp.</td></tr>';tablePager(document.querySelector('#material-pager'),rows.length,page,p=>{page=p;paint()});document.querySelectorAll('[data-remove]').forEach(b=>b.onclick=async()=>{if(!confirm('Xóa học liệu này cùng các phiên bản liên quan?'))return;try{await req(`/learning-materials/${b.dataset.remove}`,{method:'DELETE'});adminMaterials()}catch(e){note(e.message,true)}});document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>edit(materials.find(x=>x.id===b.dataset.edit)))};const edit=x=>{shell(`<h1>Cập nhật học liệu</h1><section class="card"><form id="edit-material"><label>Học phần<select name="courseId">${courses.map(c=>`<option value="${c.id}" ${c.id===x.courseId?'selected':''}>${esc(c.name)}</option>`).join('')}</select></label><label>Loại<select name="materialType">${type.map((t,i)=>`<option value="${i}" ${i===x.materialType?'selected':''}>${t}</option>`).join('')}</select></label><label class="wide">Tên học liệu<input name="title" value="${esc(x.title)}" required></label><label class="wide">Mô tả<textarea name="description">${esc(x.description||'')}</textarea></label><button>Lưu thay đổi</button></form></section>`);document.querySelector('#edit-material').onsubmit=async e=>{e.preventDefault();const body=Object.fromEntries(new FormData(e.target));body.materialType=+body.materialType;try{await req(`/learning-materials/${x.id}`,{method:'PUT',body:JSON.stringify(body)});view='admin-materials';render()}catch(err){note(err.message,true)}}};document.querySelector('#material-search').oninput=()=>{page=1;paint()};paint();
};

reports=async()=>{
  const [report,logs]=await Promise.all([req('/reports/overview'),req('/reports/audit-logs?take=200')]);let page=1;
  shell(`<section class="page-title"><div><p class="breadcrumb">BÁO CÁO / CHẤT LƯỢNG</p><h1>Báo cáo chất lượng</h1><p>Số liệu tổng hợp trực tiếp từ cơ sở dữ liệu hiện tại.</p></div></section><section class="stats"><article><b>${report.materials}</b><span>Tổng học liệu</span></article><article><b>${report.pendingApproval}</b><span>Chờ nghiệm thu</span></article><article><b>${report.needRevision}</b><span>Cần chỉnh sửa</span></article><article><b>${report.approved}</b><span>Đã nghiệm thu</span></article></section><section class="data-panel"><div class="data-panel-head"><div><h2>Chất lượng học liệu theo khoa</h2><p>${report.byDepartment.length} khoa có học liệu</p></div></div><div class="table-wrap"><table><thead><tr><th>Khoa</th><th>Tổng học liệu</th><th>Cần chỉnh sửa</th><th>Đã nghiệm thu</th></tr></thead><tbody>${report.byDepartment.map(x=>`<tr><td><b>${esc(x.department)}</b></td><td>${x.total}</td><td>${x.needRevision}</td><td>${x.approved}</td></tr>`).join('')||'<tr><td colspan="4" class="empty">Chưa có học liệu.</td></tr>'}</tbody></table></div></section><section class="data-panel"><div class="data-panel-head"><div><h2>Nhật ký hoạt động</h2><p id="log-count"></p></div><div class="data-tools"><input id="log-search" placeholder="Tìm hoạt động, người thực hiện"></div></div><div class="table-wrap"><table><thead><tr><th>Thời gian</th><th>Người thực hiện</th><th>Hoạt động</th><th>Chi tiết</th></tr></thead><tbody id="log-rows"></tbody></table></div><div id="log-pager"></div></section>`);
  const paint=()=>{const q=document.querySelector('#log-search').value.trim().toLowerCase(),rows=logs.filter(x=>!q||`${x.user} ${x.action} ${x.description}`.toLowerCase().includes(q)),size=10;page=Math.min(page,Math.max(1,Math.ceil(rows.length/size)));document.querySelector('#log-count').textContent=`${rows.length} nhật ký phù hợp`;document.querySelector('#log-rows').innerHTML=rows.slice((page-1)*size,page*size).map(x=>`<tr><td>${new Date(x.createdAt).toLocaleString('vi-VN')}</td><td>${esc(x.user)}</td><td><span class="activity">${esc(x.action)}</span></td><td>${esc(x.description)}</td></tr>`).join('')||'<tr><td colspan="4" class="empty">Không có nhật ký phù hợp.</td></tr>';tablePager(document.querySelector('#log-pager'),rows.length,page,p=>{page=p;paint()})};document.querySelector('#log-search').oninput=()=>{page=1;paint()};paint();
};

const shellBase=shell;
shell=(body)=>{shellBase(body);if(s?.role==='Admin'){const nav=document.querySelector('header nav');if(nav&&!nav.querySelector('[data-v="criteria"]')){nav.insertAdjacentHTML('beforeend','<button data-v="criteria">Bộ tiêu chí</button>');nav.querySelector('[data-v="criteria"]').onclick=()=>{view='criteria';render()}}}};
const renderBase=render;
render=async()=>{if(s&&view==='criteria')return criteria();return renderBase();};
async function criteria(){const data=await req('/quality-criteria');let page=1;const materialOptions=['Áp dụng mọi loại','PDF','Word','PowerPoint','Video','SCORM','HTML','ZIP'];shell(`<section class="page-title"><div><p class="breadcrumb">QUẢN TRỊ HỆ THỐNG / KIỂM THỬ</p><h1>Bộ tiêu chí kiểm thử</h1><p>Thiết lập tiêu chí để CCD đánh giá học liệu nhất quán.</p></div></section><details class="course-create account-create"><summary><span><b>Thêm tiêu chí</b><small>Tiêu chí được lưu trong cơ sở dữ liệu và dùng cho các lượt kiểm thử.</small></span><i>+</i></summary><form id="criterion-form"><label>Mã tiêu chí<input name="code" required placeholder="VD: OBE-01"></label><label>Tên tiêu chí<input name="name" required placeholder="VD: Có liên kết chuẩn đầu ra CLO"></label><label>Nhóm<select name="category"><option>Kỹ thuật</option><option>Nội dung</option><option>Sư phạm</option><option>OBE</option></select></label><label>Loại học liệu<select name="materialType">${materialOptions.map((x,i)=>`<option value="${i===0?'':i-1}">${x}</option>`).join('')}</select></label><label>Trọng số<input name="weight" type="number" value="1" min="1" required></label><label><input name="isRequired" type="checkbox" checked> Tiêu chí bắt buộc</label><label class="wide">Mô tả<textarea name="description" placeholder="Hướng dẫn CCD đánh giá tiêu chí này"></textarea></label><button>Lưu tiêu chí</button></form></details><section class="data-panel"><div class="data-panel-head"><div><h2>Danh sách tiêu chí</h2><p id="criterion-count"></p></div><div class="data-tools"><input id="criterion-search" placeholder="Tìm mã, tên hoặc nhóm"></div></div><div class="table-wrap"><table><thead><tr><th>Mã</th><th>Tiêu chí</th><th>Nhóm</th><th>Loại học liệu</th><th>Trọng số</th><th>Trạng thái</th></tr></thead><tbody id="criterion-rows"></tbody></table></div><div id="criterion-pager"></div></section>`);const paint=()=>{const q=document.querySelector('#criterion-search').value.toLowerCase(),rows=data.filter(x=>!q||`${x.code} ${x.name} ${x.category}`.toLowerCase().includes(q)),size=10;page=Math.min(page,Math.max(1,Math.ceil(rows.length/size)));document.querySelector('#criterion-count').textContent=`${rows.length} tiêu chí`;document.querySelector('#criterion-rows').innerHTML=rows.slice((page-1)*size,page*size).map(x=>`<tr><td><span class="code">${esc(x.code)}</span></td><td><b>${esc(x.name)}</b><small>${esc(x.description||'')}</small></td><td>${esc(x.category)}</td><td>${x.materialType===null?'Mọi loại':materialOptions[x.materialType+1]}</td><td>${x.weight}</td><td><span class="status ${x.isActive?'active':'locked'}">${x.isActive?'Đang dùng':'Ngừng dùng'}</span></td></tr>`).join('')||'<tr><td colspan="6" class="empty">Chưa có tiêu chí. Hãy tạo bộ tiêu chí đầu tiên.</td></tr>';tablePager(document.querySelector('#criterion-pager'),rows.length,page,p=>{page=p;paint()})};document.querySelector('#criterion-search').oninput=()=>{page=1;paint()};paint();document.querySelector('#criterion-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),body=Object.fromEntries(f);body.weight=+body.weight;body.materialType=body.materialType===''?null:+body.materialType;body.isRequired=f.get('isRequired')==='on';try{await req('/quality-criteria',{method:'POST',body:JSON.stringify(body)});criteria()}catch(err){note(err.message,true)}};}

async function downloadAcceptanceReport(){try{const response=await fetch(`${api}/reports/export/acceptance-csv`,{headers:{Authorization:`Bearer ${s.accessToken}`}});if(!response.ok)throw Error('Không thể xuất báo cáo.');const blob=await response.blob(),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='bao-cao-nghiem-thu.csv';a.click();URL.revokeObjectURL(url)}catch(err){note(err.message,true)}}

const reportsBase=reports;
reports=async()=>{await reportsBase();const title=document.querySelector('.page-title');if(title){title.insertAdjacentHTML('beforeend','<button id="export-report" class="export-button">Xuất báo cáo CSV</button>');document.querySelector('#export-report').onclick=downloadAcceptanceReport;}};

const materialsBase=materials;
materials=async()=>{
  const [list,feedback]=await Promise.all([req('/learning-materials'),req('/my-feedback').catch(()=>[])]);
  const byMaterial=new Map();feedback.forEach(x=>{if(!byMaterial.has(x.materialId))byMaterial.set(x.materialId,x)});
  shell(`<section class="page-title"><div><p class="breadcrumb">HỌC LIỆU / PHẢN HỒI</p><h1>Học liệu của tôi</h1><p>Theo dõi kết quả kiểm tra tự động, phản hồi CCD và nộp phiên bản chỉnh sửa.</p></div></section><section class="data-panel"><div class="data-panel-head"><div><h2>Danh sách học liệu</h2><p>${list.length} học liệu</p></div></div><div class="table-wrap"><table><thead><tr><th>Học liệu</th><th>Học phần</th><th>Trạng thái</th><th>Phản hồi CCD</th><th></th></tr></thead><tbody>${list.map(x=>{const f=byMaterial.get(x.id),issues=f?.issues||[];return`<tr><td><span class="code">${esc(x.code)}</span><br><b>${esc(x.title)}</b></td><td>${esc(x.courseName)}</td><td>${['Nháp','Đã tải','Đang xử lý AI','Đã kiểm tra AI','Chờ nghiệm thu','Cần chỉnh sửa','Đã nghiệm thu'][x.status]||''}</td><td>${issues.length?`<b>${issues.length} phiếu lỗi</b><small>${esc(issues[0].title)}</small>`:esc(f?.conclusion||'Chưa có phản hồi')}</td><td>${x.status===5?`<button class="mini" data-resubmit="${x.id}">Nộp lại</button>`:'<button class="mini" data-feedback="'+x.id+'">Xem</button>'}</td></tr>`}).join('')||'<tr><td colspan="5" class="empty">Chưa có học liệu.</td></tr>'}</tbody></table></div></section>`);
  document.querySelectorAll('[data-feedback]').forEach(b=>b.onclick=()=>{const f=byMaterial.get(b.dataset.feedback);if(!f)return note('Học liệu này chưa có phản hồi.',true);alert((f.issues||[]).map(i=>`[${i.severity}] ${i.title}\n${i.description}`).join('\n\n')||f.conclusion||'Chưa có phản hồi.')});
  document.querySelectorAll('[data-resubmit]').forEach(b=>b.onclick=()=>resubmit(b.dataset.resubmit));
  list.forEach(item=>{const cell=[...document.querySelectorAll('tbody tr')].find(row=>row.querySelector('.code')?.textContent===item.code)?.lastElementChild;if(cell){const button=document.createElement('button');button.className='mini';button.textContent='Báo cáo';button.onclick=()=>downloadMaterialReport(item.id);cell.append(' ',button)}});
  async function resubmit(materialId){shell(`<section class="page-title"><div><p class="breadcrumb">HỌC LIỆU / NỘP LẠI</p><h1>Nộp phiên bản chỉnh sửa</h1><p>Ghi rõ nội dung đã khắc phục và tải tệp phiên bản mới.</p></div></section><section class="card"><form id="resubmit-form"><label class="wide">Tệp phiên bản mới<input name="file" type="file" required accept=".pdf,.doc,.docx,.ppt,.pptx,.mp4,.zip,.html"></label><label class="wide">Nội dung đã chỉnh sửa<textarea name="remark" required placeholder="Ví dụ: Đã bổ sung CLO 2, rubric và câu hỏi đánh giá cuối bài."></textarea></label><button>Nộp lại và đánh giá tự động</button></form></section>`);document.querySelector('#resubmit-form').onsubmit=async e=>{e.preventDefault();const form=new FormData(e.target),button=e.submitter;button.disabled=true;try{form.append('learningMaterialId',materialId);const version=await req('/material-versions/upload',{method:'POST',body:form});await req('/auto-tests',{method:'POST',body:JSON.stringify({materialVersionId:version.id})});view='materials';render()}catch(err){note(err.message,true)}finally{button.disabled=false}};}
};

async function downloadMaterialReport(materialId){try{const response=await fetch(`${api}/reports/materials/${materialId}/acceptance-csv`,{headers:{Authorization:`Bearer ${s.accessToken}`}});if(!response.ok)throw Error('Chưa thể xuất báo cáo nghiệm thu cho học liệu này.');const blob=await response.blob(),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='bao-cao-nghiem-thu.csv';a.click();URL.revokeObjectURL(url)}catch(err){note(err.message,true)}}

async function printAiReport(testId,materialId){
  try{
    const [raw,materials]=await Promise.all([req(`/auto-tests/${testId}/report`),req('/learning-materials')]);
    const report=normalizeAutoReport(raw),material=materials.find(x=>x.id===materialId);
    if(!material)throw Error('Không tìm thấy thông tin học liệu để lập báo cáo.');
    const findings=report.findings.map(x=>`<tr><td>${esc(x.group)}</td><td>${esc(x.level)}</td><td>${esc(x.problem)}</td><td>${esc(x.solution)}</td></tr>`).join('')||'<tr><td colspan="4">Không có vấn đề được phát hiện.</td></tr>';
    const recommendations=report.recommendations.map(x=>`<li>${esc(x)}</li>`).join('')||'<li>Không có kiến nghị bổ sung.</li>';
    const popup=window.open('','_blank','noopener,noreferrer');if(!popup)throw Error('Trình duyệt đã chặn cửa sổ in. Hãy cho phép pop-up rồi thử lại.');
    popup.document.write(`<!doctype html><html lang="vi"><head><meta charset="utf-8"><title>Báo cáo AI - ${esc(material.code)}</title><style>body{font-family:Arial,sans-serif;color:#102a43;max-width:900px;margin:32px auto;padding:0 28px;font-size:13px}h1{font-size:25px;margin-bottom:4px}h2{font-size:17px;margin-top:28px;border-bottom:1px solid #d9e2ec;padding-bottom:7px}.muted{color:#526c88}.meta{display:grid;grid-template-columns:1fr 1fr;gap:8px 28px;background:#f5f8fc;padding:16px;border-radius:8px}.score{display:grid;grid-template-columns:repeat(5,1fr);gap:8px}.score div{border:1px solid #cbd8e6;padding:12px;border-radius:8px}.score b{display:block;font-size:22px;margin-top:4px}table{width:100%;border-collapse:collapse}th,td{border:1px solid #cbd8e6;padding:8px;vertical-align:top;text-align:left}th{background:#edf3f9}li{margin:7px 0}@media print{body{margin:0;max-width:none}.no-print{display:none}}</style></head><body><button class="no-print" onclick="print()">In / Lưu PDF</button><h1>BÁO CÁO ĐÁNH GIÁ HỌC LIỆU SỐ</h1><p class="muted">Kết quả đánh giá tự động theo tiêu chí kỹ thuật, nội dung, sư phạm và OBE.</p><section class="meta"><div><b>Mã học liệu:</b> ${esc(material.code)}</div><div><b>Tên học liệu:</b> ${esc(material.title)}</div><div><b>Học phần:</b> ${esc(material.courseName)}</div><div><b>Người nộp:</b> ${esc(material.ownerName||'')}</div><div><b>Phương pháp:</b> ${esc(report.assessmentMethod)}</div><div><b>Nguồn tệp:</b> ${report.fileTextExtracted?`Đã trích xuất ${Number(report.extractedCharacterCount).toLocaleString('vi-VN')} ký tự` : esc(report.extractionNotice||'Không đọc được nội dung tệp')}</div></section><h2>Kết quả</h2><div class="score"><div>Điểm tổng<b>${report.overallScore}/100</b></div><div>Kỹ thuật<b>${report.technicalScore}/100</b></div><div>Nội dung<b>${report.contentScore}/100</b></div><div>Sư phạm<b>${report.pedagogyScore}/100</b></div><div>OBE<b>${report.obeScore}/100</b></div></div><p><b>Kết luận:</b> ${esc(report.verdict)}<br><b>Ý kiến:</b> ${esc(report.opinion)}</p><h2>Vấn đề cần khắc phục</h2><table><thead><tr><th>Nhóm</th><th>Mức độ</th><th>Vấn đề</th><th>Cách thực hiện</th></tr></thead><tbody>${findings}</tbody></table><h2>Kiến nghị</h2><ol>${recommendations}</ol><p class="muted">Ngày xuất: ${new Date().toLocaleString('vi-VN')}</p></body></html>`);
    popup.document.close();popup.focus();setTimeout(()=>popup.print(),300);
  }catch(error){note(error.message,true)}
}

/* Người dùng tự đổi mật khẩu: bắt buộc với mật khẩu tạm, luôn có thể mở lại từ thanh đầu trang. */
async function passwordPage(required=false){
  shell(`<section class="page-title"><div><p class="breadcrumb">TÀI KHOẢN / BẢO MẬT</p><h1>${required?'Thiết lập mật khẩu cá nhân':'Đổi mật khẩu'}</h1><p>${required?'Đây là lần đăng nhập đầu tiên. Hãy đổi mật khẩu tạm do Quản trị viên cấp trước khi sử dụng hệ thống.':'Cập nhật mật khẩu để bảo vệ tài khoản của bạn.'}</p></div></section><section class="password-card"><div class="password-card-side"><span>01</span><b>Bảo mật tài khoản</b><p>Mật khẩu mới phải có ít nhất 6 ký tự và không trùng mật khẩu tạm.</p></div><form id="change-password-form"><label>Mật khẩu hiện tại<input name="oldPassword" type="password" autocomplete="current-password" required></label><label>Mật khẩu mới<input name="newPassword" type="password" autocomplete="new-password" minlength="6" required></label><label>Xác nhận mật khẩu mới<input name="confirmPassword" type="password" autocomplete="new-password" minlength="6" required></label><p id="password-error" class="error"></p><button>${required?'Hoàn tất thiết lập':'Lưu mật khẩu mới'}</button>${required?'':'<button type="button" class="mini" id="cancel-password">Hủy</button>'}</form></section>`);
  document.querySelector('#change-password-form').onsubmit=async e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.target)),error=document.querySelector('#password-error'),button=e.submitter;if(data.newPassword!==data.confirmPassword){error.textContent='Xác nhận mật khẩu mới chưa khớp.';return}if(data.newPassword===data.oldPassword){error.textContent='Mật khẩu mới cần khác mật khẩu tạm/mật khẩu hiện tại.';return}button.disabled=true;try{await req('/auth/change-password',{method:'POST',body:JSON.stringify({oldPassword:data.oldPassword,newPassword:data.newPassword})});s.isFirstLogin=false;sessionStorage.setItem('session',JSON.stringify(s));view='dashboard';await render()}catch(err){error.textContent=err.message}finally{button.disabled=false}};
  document.querySelector('#cancel-password')?.addEventListener('click',()=>{view='dashboard';render()});
}

const shellForPassword=shell;
shell=(body)=>{shellForPassword(body);if(!s)return;const out=document.querySelector('#out');if(out&&!document.querySelector('#change-password')){out.insertAdjacentHTML('beforebegin','<button id="change-password" class="password-link" title="Đổi mật khẩu">Đổi mật khẩu</button>');document.querySelector('#change-password').onclick=()=>{view='change-password';render()}}};

const renderForPassword=render;
render=async()=>{if(s?.isFirstLogin&&view!=='change-password')return passwordPage(true);if(s&&view==='change-password')return passwordPage(false);return renderForPassword();};

/* Nộp học liệu theo danh mục thật: Khoa → Ngành → Học phần. */
submit=async()=>{
  const [departments,majors,courses]=await Promise.all([req('/departments'),req('/majors'),req('/courses')]);
  shell(`<section class="page-title"><div><p class="breadcrumb">HỌC LIỆU / NỘP MỚI</p><h1>Nộp học liệu để đánh giá</h1><p>Chọn đúng khoa, ngành và học phần đã được Quản trị viên khai báo.</p></div></section><section class="card submit-card"><form id="submit"><label>Mã học liệu<input name="code" required placeholder="VD: HL-OBE-001"></label><label>Tên học liệu<input name="title" required placeholder="Nhập tên học liệu"></label><label>Khoa<select id="submit-department" required><option value="">Chọn khoa</option>${departments.map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('')}</select></label><label>Ngành<select id="submit-major" required disabled><option value="">Chọn khoa trước</option></select></label><label class="wide">Học phần<select id="submit-course" name="courseId" required disabled><option value="">Chọn ngành trước</option></select><small id="course-help">Danh sách chỉ gồm học phần đã lưu trong hệ thống.</small></label><label>Loại học liệu<select name="materialType">${type.map((x,i)=>`<option value="${i}">${x}</option>`).join('')}</select></label><label class="wide">Mô tả, CLO, hoạt động, câu hỏi<textarea name="description" placeholder="Mô tả nội dung, CLO liên quan, hoạt động học tập và minh chứng đánh giá."></textarea></label><label class="wide">Tệp học liệu<input name="file" required type="file" accept=".pdf,.doc,.docx,.ppt,.pptx,.mp4,.zip,.html"></label><button>Nộp và chạy kiểm thử tự động</button></form></section>`);
  const department=document.querySelector('#submit-department'),major=document.querySelector('#submit-major'),course=document.querySelector('#submit-course'),help=document.querySelector('#course-help');
  const fillCourses=()=>{const rows=courses.filter(x=>x.departmentId===department.value&&(!major.value||x.majorId===major.value));course.disabled=!rows.length;course.innerHTML=rows.length?'<option value="">Chọn học phần</option>'+rows.map(x=>`<option value="${x.id}">${esc(x.code)} – ${esc(x.name)}${x.majorName?' · '+esc(x.majorName):' · Học phần chung'}</option>`).join(''):'<option value="">Khoa/ngành này chưa có học phần</option>';help.textContent=rows.length?`Có ${rows.length} học phần đã được khai báo. Bạn có thể dùng bộ lọc ngành hoặc chọn trực tiếp.`:'Chưa có học phần thật được khai báo cho lựa chọn này. Liên hệ Quản trị viên để bổ sung danh mục.';};
  department.onchange=()=>{const rows=majors.filter(x=>x.departmentId===department.value);major.disabled=false;major.innerHTML='<option value="">Tất cả ngành trong khoa</option>'+rows.map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('');fillCourses();};
  major.onchange=fillCourses;
  document.querySelector('#submit').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),button=e.submitter;button.disabled=true;try{const material=await req('/learning-materials',{method:'POST',body:JSON.stringify({code:f.get('code'),courseId:f.get('courseId'),title:f.get('title'),description:f.get('description')||null,materialType:+f.get('materialType')})}),upload=new FormData();upload.append('learningMaterialId',material.id);upload.append('file',f.get('file'));upload.append('remark',f.get('description')||'');const version=await req('/material-versions/upload',{method:'POST',body:upload});const test=await req('/auto-tests',{method:'POST',body:JSON.stringify({materialVersionId:version.id})});await showAutoAssessment(test.id,material.id)}catch(err){note(err.message,true)}finally{button.disabled=false}};
};

/* Không gửi yêu cầu thiếu học phần: đây là điều kiện nghiệp vụ trước khi AI có thể đánh giá. */
const submitWithCourseGuard=submit;
submit=async()=>{
  await submitWithCourseGuard();
  const form=document.querySelector('#submit'),course=document.querySelector('#submit-course'),button=form?.querySelector('button[type="submit"], button:last-of-type'),help=document.querySelector('#course-help');
  if(!form||!course||!button)return;
  const updateSubmitState=()=>{button.disabled=!course.value;button.title=course.value?'':'Hãy chọn học phần trước khi nộp học liệu.';};
  const originalSubmit=form.onsubmit;
  form.onsubmit=async event=>{if(!course.value){event.preventDefault();note('Chưa thể chạy kiểm thử tự động vì chưa có học phần được chọn. Hãy chọn khoa có học phần đã khai báo, hoặc nhờ Quản trị viên thêm học phần thật cho khoa/ngành này.',true);help.textContent='Cần chọn một học phần trước khi nộp. AI sẽ đánh giá học liệu theo học phần và chuẩn đầu ra liên quan.';return;}return originalSubmit(event);};
  course.addEventListener('change',updateSubmitState);updateSubmitState();
};

/* Chuyển thông báo kiểm tra dữ liệu mặc định của ASP.NET sang tiếng Việt. */
const requestWithVietnameseErrors=req;
req=async(...args)=>{try{return await requestWithVietnameseErrors(...args)}catch(error){if(error?.message==='One or more validation errors occurred.')throw Error('Thông tin gửi lên chưa hợp lệ. Vui lòng kiểm tra và chọn đầy đủ học phần, tệp học liệu.');throw error}};

