dashboard=async()=>{
  const materials=await req('/learning-materials');
  const own=s.role==='Lecturer'?materials:materials.filter(x=>x.ownerId===s.userId);
  const count=status=>own.filter(x=>x.status===status).length;
  const rows=own.slice(0,5).map(x=>`<tr><td><span class="code">${esc(x.code)}</span></td><td><b>${esc(x.title)}</b><small>${esc(x.courseName)}</small></td><td>${['Nháp','Đã tải tệp','Đang xử lý AI','Đã có kết quả AI','Chờ nghiệm thu','Cần chỉnh sửa','Đã nghiệm thu'][x.status]||'Chưa xác định'}</td></tr>`).join('')||'<tr><td colspan="3" class="empty">Chưa có học liệu. Hãy nộp học liệu đầu tiên để bắt đầu kiểm thử.</td></tr>';
  shell(`<section class="page-title dashboard-title"><div><p class="breadcrumb">KHÔNG GIAN LÀM VIỆC</p><h1>Xin chào, ${esc(s.fullName)}</h1><p>Quản lý chất lượng học liệu theo chuẩn đầu ra OBE.</p></div></section><section class="submit-hero"><div><span>HỌC LIỆU MỚI</span><h2>Nộp học liệu và nhận kết quả AI ngay</h2><p>AI tự chấm điểm kỹ thuật, nội dung, sư phạm và OBE; đồng thời chỉ ra lỗi và hướng khắc phục.</p></div><button id="start-submit">Nộp học liệu <b>→</b></button></section><section class="stats"><article><b>${own.length}</b><span>Học liệu của tôi</span></article><article><b>${count(3)+count(4)}</b><span>Đang chờ xử lý</span></article><article><b>${count(5)}</b><span>Cần chỉnh sửa</span></article><article><b>${count(6)}</b><span>Đã nghiệm thu</span></article></section><section class="dashboard-grid"><section class="data-panel dashboard-materials"><div class="data-panel-head"><div><h2>Học liệu gần đây</h2><p>Dữ liệu lấy trực tiếp từ hệ thống</p></div><button id="view-materials" class="mini">Xem tất cả</button></div><div class="table-wrap"><table><thead><tr><th>Mã</th><th>Học liệu</th><th>Trạng thái</th></tr></thead><tbody>${rows}</tbody></table></div></section><aside class="dashboard-actions"><section class="data-panel"><h2>Việc cần làm</h2><p><b>${count(5)} học liệu</b> đang cần chỉnh sửa.</p><p><b>${count(3)+count(4)} học liệu</b> đang có kết quả AI hoặc chờ nghiệm thu.</p><button id="open-materials" class="mini">Theo dõi học liệu</button></section><section class="process-card"><p>QUY TRÌNH CHẤT LƯỢNG</p><ol><li><b>Nộp học liệu</b><span>Tệp và thông tin học phần</span></li><li><b>AI đánh giá</b><span>Điểm, lỗi, hướng khắc phục</span></li><li><b>CCD nghiệm thu</b><span>Kiểm tra thực tế và phê duyệt</span></li></ol></section></aside></section>`);
  document.querySelector('#start-submit').onclick=()=>{view='submit';render()};document.querySelector('#view-materials').onclick=()=>{view='materials';render()};document.querySelector('#open-materials').onclick=()=>{view='materials';render()};
};

function normalizeAutoReport(raw){const findings=(raw?.findings??raw?.Findings??[]).map(x=>({group:x.group??x.Group??'',level:x.level??x.Level??'',problem:x.problem??x.Problem??'',solution:x.solution??x.Solution??''}));return {overallScore:raw?.overallScore??raw?.OverallScore??0,technicalScore:raw?.technicalScore??raw?.TechnicalScore??0,contentScore:raw?.contentScore??raw?.ContentScore??0,pedagogyScore:raw?.pedagogyScore??raw?.PedagogyScore??0,obeScore:raw?.obeScore??raw?.ObeScore??0,verdict:raw?.verdict??raw?.Verdict??'',opinion:raw?.opinion??raw?.Opinion??'',assessmentMethod:raw?.assessmentMethod??raw?.AssessmentMethod??'Kiểm tra quy tắc và nội dung tệp',fileTextExtracted:raw?.fileTextExtracted??raw?.FileTextExtracted??false,extractedCharacterCount:raw?.extractedCharacterCount??raw?.ExtractedCharacterCount??0,extractionNotice:raw?.extractionNotice??raw?.ExtractionNotice??'',findings,recommendations:raw?.recommendations??raw?.Recommendations??[]};}

async function showAutoAssessment(testId,materialId){
  const report=normalizeAutoReport(await req(`/auto-tests/${testId}/report`)),findings=report.findings||[],recommendations=report.recommendations||[],verdict=report.verdict||(report.overallScore>=80?'Đạt kiểm thử tự động':'Chưa đạt kiểm thử tự động'),opinion=report.opinion||'Kết quả được AI tổng hợp từ tệp và thông tin học liệu đã nộp.';
  shell(`<section class="page-title"><div><p class="breadcrumb">ĐÁNH GIÁ TỰ ĐỘNG / KẾT QUẢ</p><h1>Kết quả kiểm thử học liệu</h1><p>${esc(report.assessmentMethod)}. Kết quả được lưu cùng phiên bản học liệu vừa nộp.</p></div><button id="download-ai-report" class="export-button">Xuất báo cáo AI</button></section><section class="ai-result-score"><article><span>Điểm tổng</span><b>${report.overallScore}<small>/100</small></b><p>${esc(verdict)}</p></article><article><span>Kỹ thuật</span><b>${report.technicalScore}<small>/100</small></b></article><article><span>Nội dung</span><b>${report.contentScore}<small>/100</small></b></article><article><span>Sư phạm</span><b>${report.pedagogyScore}<small>/100</small></b></article><article><span>OBE</span><b>${report.obeScore}<small>/100</small></b></article></section><section class="data-panel"><div class="data-panel-head"><div><h2>Vấn đề cần giải quyết</h2><p>${findings.length} vấn đề được phát hiện tự động</p></div></div>${findings.length?`<div class="finding-table"><table><thead><tr><th>Nhóm</th><th>Mức độ</th><th>Vấn đề</th><th>Cách thực hiện</th></tr></thead><tbody>${findings.map(x=>`<tr><td>${esc(x.group)}</td><td><span class="status locked">${esc(x.level)}</span></td><td>${esc(x.problem)}</td><td>${esc(x.solution)}</td></tr>`).join('')}</tbody></table></div>`:'<p class="empty">Chưa phát hiện lỗi từ các dữ liệu đã nộp. Học liệu đã được chuyển cho CCD kiểm tra nội dung thực tế và nghiệm thu.</p>'}</section><section class="data-panel"><div class="data-panel-head"><div><h2>Kiến nghị cần bổ sung</h2><p>Ưu tiên xử lý các nội dung dưới đây trước khi nộp lại hoặc chuyển nghiệm thu.</p></div></div><ol class="recommendations">${recommendations.map(x=>`<li>${esc(x)}</li>`).join('')}</ol><button id="my-materials" class="mini">Theo dõi học liệu của tôi</button></section>`);
  document.querySelector('#download-ai-report').onclick=()=>printAiReport(testId,materialId);document.querySelector('#my-materials').onclick=()=>{view='materials';render()};
}

dashboard=async()=>{
  const [materials,tests]=await Promise.all([req('/learning-materials'),req('/test-requests')]);
  const ownMaterials=s.role==='Lecturer'?materials:materials.filter(x=>x.ownerId===s.userId);
  shell(`<section class="page-title"><div><p class="breadcrumb">KHÔNG GIAN LÀM VIỆC / ${esc(roleName[s.role]||s.role).toUpperCase()}</p><h1>Tổng quan học liệu</h1><p>Nộp học liệu, nhận đánh giá tự động và theo dõi quá trình nghiệm thu.</p></div></section><section class="submit-hero"><div><span>HỌC LIỆU MỚI</span><h2>Bạn có học liệu cần kiểm tra?</h2><p>Giảng viên và chuyên viên CCD đều có thể nộp học liệu. AI sẽ chấm điểm, chỉ ra lỗi và đề xuất cách khắc phục ngay sau khi nộp.</p></div><button id="start-submit">Nộp học liệu <b>→</b></button></section><section class="stats"><article><b>${ownMaterials.length}</b><span>Học liệu của tôi</span></article><article><b>${tests.length}</b><span>Lượt kiểm thử</span></article><article><b>${ownMaterials.filter(x=>x.status===5).length}</b><span>Cần chỉnh sửa</span></article><article><b>${ownMaterials.filter(x=>x.status===6).length}</b><span>Đã nghiệm thu</span></article></section>`);
  document.querySelector('#start-submit').onclick=()=>{view='submit';render()};
};

/* Bản nộp học liệu ổn định: học phần được chọn trực tiếp theo khoa; ngành chỉ dùng để lọc. */
submit=async()=>{
  const [departments,majors,courses]=await Promise.all([req('/departments'),req('/majors'),req('/courses')]);
  shell(`<section class="page-title"><div><p class="breadcrumb">HỌC LIỆU / NỘP MỚI</p><h1>Nộp học liệu để đánh giá</h1><p>Chọn khoa và học phần. Ngành là bộ lọc tùy chọn.</p></div></section><section class="card submit-card"><form id="submit"><label>Mã học liệu<input name="code" required placeholder="VD: HL-OBE-001"></label><label>Tên học liệu<input name="title" required placeholder="Nhập tên học liệu"></label><label>Khoa<select id="submit-department" required><option value="">Chọn khoa</option>${departments.map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('')}</select></label><label>Ngành <small>(không bắt buộc)</small><select id="submit-major" disabled><option value="">Chọn khoa trước</option></select></label><label class="wide">Học phần<select id="submit-course" name="courseId" required disabled><option value="">Chọn khoa trước</option></select><small id="course-help">Chọn khoa để hiển thị học phần đã khai báo.</small></label><label>Loại học liệu<select name="materialType">${type.map((x,i)=>`<option value="${i}">${x}</option>`).join('')}</select></label><label class="wide">Mô tả, CLO, hoạt động, câu hỏi<textarea name="description" placeholder="Mô tả nội dung, CLO liên quan, hoạt động học tập và minh chứng đánh giá."></textarea></label><label class="wide">Tệp học liệu<input name="file" required type="file" accept=".pdf,.doc,.docx,.ppt,.pptx,.mp4,.zip,.html,.htm"></label><button>Nộp và chạy kiểm thử tự động</button></form></section>`);
  const department=document.querySelector('#submit-department'),major=document.querySelector('#submit-major'),course=document.querySelector('#submit-course'),help=document.querySelector('#course-help');
  const paintCourses=()=>{const rows=courses.filter(x=>x.departmentId===department.value&&(!major.value||x.majorId===major.value));course.disabled=!rows.length;course.innerHTML=rows.length?'<option value="">Chọn học phần</option>'+rows.map(x=>`<option value="${x.id}">${esc(x.code)} – ${esc(x.name)}${x.majorName?' · '+esc(x.majorName):' · Học phần chung'}</option>`).join(''):'<option value="">Chưa có học phần thuộc lựa chọn này</option>';help.textContent=rows.length?`Có ${rows.length} học phần. Bạn có thể chọn trực tiếp hoặc lọc tiếp theo ngành.`:'Chưa có học phần được khai báo cho khoa/ngành này. Quản trị viên cần thêm học phần thật vào danh mục.';};
  department.onchange=()=>{const rows=majors.filter(x=>x.departmentId===department.value);major.disabled=false;major.innerHTML='<option value="">Tất cả ngành trong khoa</option>'+rows.map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('');paintCourses();};major.onchange=paintCourses;
  document.querySelector('#submit').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),button=e.submitter;button.disabled=true;button.textContent='Đang tải và kiểm thử…';try{const material=await req('/learning-materials',{method:'POST',body:JSON.stringify({code:f.get('code'),courseId:f.get('courseId'),title:f.get('title'),description:f.get('description')||null,materialType:+f.get('materialType')})}),upload=new FormData();upload.append('learningMaterialId',material.id);upload.append('file',f.get('file'));upload.append('remark',f.get('description')||'');const version=await req('/material-versions/upload',{method:'POST',body:upload}),test=await req('/auto-tests',{method:'POST',body:JSON.stringify({materialVersionId:version.id})});try{await showAutoAssessment(test.id,material.id)}catch(reportError){view='materials';await render();note(`AI đã hoàn thành kiểm thử. Không thể mở màn chi tiết: ${reportError.message}`,true)}}catch(err){note(err.message,true)}finally{if(document.contains(button)){button.disabled=false;button.textContent='Nộp và chạy kiểm thử tự động'}}};
};

const accountAdminBase=accountAdmin;
accountAdmin=async()=>{await accountAdminBase();const accounts=await req('/users');const anchor=document.querySelector('.account-create');if(!anchor)return;anchor.insertAdjacentHTML('afterend',`<details class="course-create password-reset"><summary><span><b>Đặt lại mật khẩu</b><small>Dùng khi người dùng quên mật khẩu hoặc không đăng nhập được.</small></span><i>+</i></summary><form id="reset-password-form"><label>Tài khoản<select name="id" required>${accounts.filter(x=>x.role!=='Admin').map(x=>`<option value="${x.id}">${esc(x.fullName)} · ${esc(x.username)} · ${esc(roleName[x.role]||x.role)}</option>`).join('')}</select></label><label>Mật khẩu mới<input name="newPassword" type="password" minlength="6" required placeholder="Ít nhất 6 ký tự"></label><button>Đặt lại mật khẩu và mở khóa</button></form></details>`);document.querySelector('#reset-password-form').onsubmit=async e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.target));try{await req(`/users/${data.id}/reset-password`,{method:'PUT',body:JSON.stringify({newPassword:data.newPassword})});note('Đã đặt lại mật khẩu. Hãy gửi mật khẩu mới cho người dùng qua kênh an toàn.')}catch(err){note(err.message,true)}};};

/* Báo cáo AI của từng học liệu: Giảng viên và CCD đều xem, xuất và nộp lại được. */
materials=async()=>{
  const [list,feedback]=await Promise.all([req('/learning-materials'),req('/my-feedback').catch(()=>[])]);
  const byMaterial=new Map();feedback.forEach(x=>{if(!byMaterial.has(x.materialId))byMaterial.set(x.materialId,x)});
  const parseReport=value=>{const prefix='[AUTO_ASSESSMENT]';if(!value?.startsWith(prefix))return null;try{return normalizeAutoReport(JSON.parse(value.slice(prefix.length)))}catch{return null}};
  const status=x=>['Nháp','Đã tải tệp','Đang xử lý AI','Đã có kết quả AI','Chờ nghiệm thu','Cần chỉnh sửa','Đã nghiệm thu'][x]||'Chưa xác định';
  shell(`<section class="page-title"><div><p class="breadcrumb">HỌC LIỆU / KẾT QUẢ AI</p><h1>Học liệu và báo cáo AI</h1><p>AI đánh giá toàn bộ học liệu. Giảng viên hoặc CCD xuất báo cáo và xác nhận nghiệm thu khi đạt.</p></div></section><section class="data-panel"><div class="data-panel-head"><div><h2>Danh sách học liệu</h2><p>${list.length} học liệu</p></div></div><div class="table-wrap"><table><thead><tr><th>Học liệu</th><th>Học phần</th><th>Kết quả AI</th><th>Trạng thái</th><th></th></tr></thead><tbody>${list.map(x=>{const f=byMaterial.get(x.id),report=parseReport(f?.conclusion),canAccept=report&&report.overallScore>=80&&!report.findings.some(i=>i.level==='Cao')&&x.status!==6;return`<tr><td><span class="code">${esc(x.code)}</span><br><b>${esc(x.title)}</b></td><td>${esc(x.courseName)}</td><td>${report?`<b>${report.overallScore}/100 · ${esc(report.verdict||'Đã đánh giá')}</b><small>${esc(report.opinion||'')}</small>`:'Chưa có kết quả AI'}</td><td><span class="status ${x.status===5?'locked':x.status===6?'active':''}">${status(x.status)}</span></td><td>${report?`<button class="mini" data-ai="${f.id}" data-material="${x.id}">Xem AI</button> <button class="mini" data-export="${x.id}">Xuất</button>`:''} <button class="mini" data-history="${x.id}">Lịch sử</button>${canAccept?` <button class="mini" data-accept="${f.id}">Nghiệm thu AI</button>`:''}${x.status===5?` <button class="mini danger" data-resubmit="${x.id}">Nộp lại</button>`:''}</td></tr>`}).join('')||'<tr><td colspan="5" class="empty">Chưa có học liệu.</td></tr>'}</tbody></table></div></section>`);
  document.querySelectorAll('[data-ai]').forEach(b=>b.onclick=()=>showAutoAssessment(b.dataset.ai,b.dataset.material));document.querySelectorAll('[data-export]').forEach(b=>b.onclick=()=>downloadMaterialReport(b.dataset.export));document.querySelectorAll('[data-resubmit]').forEach(b=>b.onclick=()=>resubmitMaterial(b.dataset.resubmit));document.querySelectorAll('[data-accept]').forEach(b=>b.onclick=async()=>{if(!confirm('Xác nhận nghiệm thu học liệu theo báo cáo AI này?'))return;try{await req(`/auto-tests/${b.dataset.accept}/acceptance`,{method:'POST'});note('Đã nghiệm thu học liệu theo kết quả AI.');await materials()}catch(error){note(error.message,true)}});
  document.querySelectorAll('[data-history]').forEach(b=>b.onclick=()=>showAssessmentHistory(b.dataset.history));
};

async function resubmitMaterial(materialId){shell(`<section class="page-title"><div><p class="breadcrumb">HỌC LIỆU / NỘP LẠI</p><h1>Nộp phiên bản chỉnh sửa</h1><p>Tải phiên bản mới, AI sẽ chấm lại và tạo báo cáo mới.</p></div></section><section class="card"><form id="resubmit-form"><label class="wide">Tệp phiên bản mới<input name="file" type="file" required accept=".pdf,.doc,.docx,.ppt,.pptx,.mp4,.zip,.html,.htm"></label><label class="wide">Nội dung đã khắc phục<textarea name="remark" required></textarea></label><button>Nộp lại và AI đánh giá</button></form></section>`);document.querySelector('#resubmit-form').onsubmit=async e=>{e.preventDefault();const form=new FormData(e.target),button=e.submitter;button.disabled=true;try{form.append('learningMaterialId',materialId);const version=await req('/material-versions/upload',{method:'POST',body:form}),test=await req('/auto-tests',{method:'POST',body:JSON.stringify({materialVersionId:version.id})});await showAutoAssessment(test.id,materialId)}catch(error){note(error.message,true)}finally{button.disabled=false}};}

async function showAssessmentHistory(materialId){
  const history=await req(`/material-versions/${materialId}/assessment-history`);
  const parse=value=>{const prefix='[AUTO_ASSESSMENT]';try{return value?.startsWith(prefix)?normalizeAutoReport(JSON.parse(value.slice(prefix.length))):null}catch{return null}};
  const ordered=[...history].sort((a,b)=>a.versionNumber-b.versionNumber);
  const scoreOf=x=>parse(x.test?.conclusion)?.overallScore;
  shell(`<section class="page-title"><div><p class="breadcrumb">HỌC LIỆU / LỊCH SỬ CẢI TIẾN</p><h1>Lịch sử đánh giá và nộp lại</h1><p>Mỗi phiên bản được lưu độc lập để theo dõi việc khắc phục sau phản hồi AI.</p></div><button id="back-materials" class="export-button">← Học liệu của tôi</button></section><section class="data-panel"><div class="data-panel-head"><div><h2>So sánh các phiên bản</h2><p>${ordered.length} phiên bản đã nộp</p></div></div><div class="table-wrap"><table><thead><tr><th>Phiên bản</th><th>Thời điểm nộp</th><th>Nội dung đã sửa</th><th>Điểm AI</th><th>Thay đổi</th><th>Kết luận</th></tr></thead><tbody>${ordered.map((x,index)=>{const report=parse(x.test?.conclusion),score=scoreOf(x),previous=index?scoreOf(ordered[index-1]):null,delta=Number.isFinite(score)&&Number.isFinite(previous)?score-previous:null;return `<tr><td><span class="code">v${x.versionNumber}</span><small>${esc(x.fileName)}</small></td><td>${new Date(x.uploadDate).toLocaleString('vi-VN')}</td><td>${esc(x.remark||'Chưa ghi chú')}</td><td>${Number.isFinite(score)?`<b>${score}/100</b>`:'Chưa có báo cáo'}</td><td>${delta===null?'—':`<b class="${delta>=0?'score-up':'score-down'}">${delta>=0?'+':''}${delta} điểm</b>`}</td><td>${report?esc(report.verdict||'Đã đánh giá'):'Đang chờ'}</td></tr>`}).join('')}</tbody></table></div></section><section class="data-panel"><h2>Quy trình nộp lại</h2><p>Khi AI kết luận chưa đạt, hệ thống giữ nguyên báo cáo cũ, cho phép tải phiên bản chỉnh sửa và chấm lại. CCD chỉ tiếp nhận các phiên bản đạt ngưỡng kiểm thử tự động để nghiệm thu thực tế.</p></section>`);
  document.querySelector('#back-materials').onclick=()=>{view='materials';render()};
}

dashboard=async()=>{
  const materials=await req('/learning-materials'),own=s.role==='Lecturer'?materials:materials.filter(x=>x.ownerId===s.userId),count=v=>own.filter(x=>x.status===v).length;
  shell(`<section class="page-title dashboard-title"><div><p class="breadcrumb">KHÔNG GIAN LÀM VIỆC</p><h1>Xin chào, ${esc(s.fullName)}</h1><p>Quản lý chất lượng học liệu theo chuẩn đầu ra OBE.</p></div></section><section class="submit-hero"><div><span>HỌC LIỆU MỚI</span><h2>Nộp học liệu và nhận kết quả AI ngay</h2><p>AI chấm điểm, kết luận đạt/chưa đạt kiểm thử tự động, nêu lỗi và hướng khắc phục cụ thể.</p></div><button id="start-submit">Nộp học liệu <b>→</b></button></section><section class="stats"><article><b>${own.length}</b><span>Học liệu của tôi</span></article><article><b>${count(3)+count(4)}</b><span>Đang chờ xử lý</span></article><article><b>${count(5)}</b><span>Cần chỉnh sửa</span></article><article><b>${count(6)}</b><span>Đã nghiệm thu</span></article></section><section class="dashboard-grid"><section class="data-panel"><h2>Truy cập nhanh</h2><p>Nộp học liệu mới để AI đánh giá, hoặc xem lại toàn bộ báo cáo AI đã có.</p><button id="dashboard-materials" class="mini">Xem báo cáo AI</button></section><aside class="process-card"><p>QUY TRÌNH CHẤT LƯỢNG</p><ol><li><b>Nộp học liệu</b><span>Tệp và thông tin học phần</span></li><li><b>AI đánh giá</b><span>Điểm, đạt/chưa đạt, lỗi, kiến nghị</span></li><li><b>CCD nghiệm thu</b><span>Kiểm tra thực tế và phê duyệt</span></li></ol></aside></section>`);document.querySelector('#start-submit').onclick=()=>{view='submit';render()};document.querySelector('#dashboard-materials').onclick=()=>{view='materials';render()};
};

/* Không dựng dữ liệu mẫu: hàng chờ, checklist và phiếu lỗi đều gọi API CCD/SQL Server. */
/* Khi danh mục chưa có học phần, người nộp nhập học phần thực tế ngay tại màn nộp. */
const submitWithCourseEntry=submit;
submit=async()=>{
  await submitWithCourseEntry();
  const help=document.querySelector('#course-help'),department=document.querySelector('#submit-department'),major=document.querySelector('#submit-major'),course=document.querySelector('#submit-course');
  if(!help||!department||!major||!course||document.querySelector('#self-course-entry'))return;
  help.insertAdjacentHTML('afterend','<details id="self-course-entry" class="self-course-entry"><summary>Chưa có học phần? Nhập học phần thực tế để tiếp tục nộp <span>+</span></summary><div id="self-course-form"><label>Mã học phần<input name="code" placeholder="VD: BIO101"></label><label>Tên học phần<input name="name" placeholder="VD: Sinh học đại cương"></label><label>Tín chỉ<input name="credits" type="number" min="1" max="20" value="3"></label><label>Học kỳ<input name="semester" value="1"></label><label>Năm học<input name="academicYear" value="2026-2027"></label><button type="button" id="save-self-course">Thêm học phần và chọn</button></div></details>');
  document.querySelector('#save-self-course').onclick=async()=>{if(!department.value)return note('Hãy chọn khoa trước khi nhập học phần.',true);const entry=document.querySelector('#self-course-form'),data=Object.fromEntries(new FormData());for(const input of entry.querySelectorAll('[name]'))data[input.name]=input.value;if(!data.code?.trim()||!data.name?.trim()||!data.credits||!data.semester?.trim()||!data.academicYear?.trim())return note('Vui lòng nhập đầy đủ thông tin học phần.',true);data.departmentId=department.value;data.majorId=major.value||null;data.credits=+data.credits;const button=document.querySelector('#save-self-course');button.disabled=true;try{const created=await req('/courses/self-service',{method:'POST',body:JSON.stringify(data)});course.disabled=false;course.insertAdjacentHTML('beforeend',`<option value="${created.id}" selected>${esc(data.code)} – ${esc(data.name)} · Học phần vừa nhập</option>`);course.value=created.id;help.textContent='Đã thêm học phần từ thông tin bạn nhập và chọn cho học liệu này.';document.querySelector('#self-course-entry').remove()}catch(error){note(error.message,true)}finally{button.disabled=false}};
};

/* Hiển thị bảng trọng số chấm AI: 4 nhóm x 25 điểm, tổng đúng 100 điểm. */
const showAutoAssessmentWithBreakdown=showAutoAssessment;
showAutoAssessment=async(testId,materialId)=>{
  await showAutoAssessmentWithBreakdown(testId,materialId);
  const report=normalizeAutoReport(await req(`/auto-tests/${testId}/report`)),anchor=document.querySelector('.ai-result-score');
  if(!anchor||document.querySelector('.score-breakdown'))return;
  anchor.insertAdjacentHTML('beforebegin',`<section class="data-panel assessment-source"><div class="data-panel-head"><div><h2>Nguồn dữ liệu đánh giá</h2><p>${report.fileTextExtracted?`Đã trích xuất ${Number(report.extractedCharacterCount).toLocaleString('vi-VN')} ký tự trực tiếp từ tệp học liệu.`:esc(report.extractionNotice||'Không trích xuất được văn bản trực tiếp từ tệp.')}</p></div><span class="status ${report.fileTextExtracted?'active':'locked'}">${report.fileTextExtracted?'Đã đọc nội dung tệp':'Chưa đọc được nội dung tệp'}</span></div></section>`);
  const rows=[['Kỹ thuật',report.technicalScore,'Khả năng mở tệp, định dạng và tính toàn vẹn'],['Nội dung',report.contentScore,'Mục tiêu, chủ đề và phạm vi nội dung'],['Sư phạm',report.pedagogyScore,'Hướng dẫn, hoạt động và tương tác học tập'],['OBE',report.obeScore,'CLO, công cụ đánh giá và minh chứng']];
  anchor.insertAdjacentHTML('afterend',`<section class="data-panel score-breakdown"><div class="data-panel-head"><div><h2>Chi tiết điểm AI theo tiêu chí</h2><p>Mỗi nhóm tối đa 25 điểm; điểm tổng là tổng của 4 nhóm.</p></div><b class="score-total">${report.overallScore}/100</b></div><div class="score-rows">${rows.map(([name,score,detail])=>`<article><div><b>${name}</b><small>${detail}</small></div><div class="score-bar"><i style="width:${Math.max(0,Math.min(100,score))}%"></i></div><strong>${Math.round(score/4)}<small>/25</small></strong></article>`).join('')}</div></section>`);
};

const shellWithNotifications=shell;
shell=(body)=>{
  shellWithNotifications(body);
  const userArea=document.querySelector('header .user');
  if(!userArea)return;
  userArea.insertAdjacentHTML('afterbegin','<button id="notification-toggle" class="notification-toggle" title="Thông báo">Thông báo <span>0</span></button><section id="notification-panel" class="notification-panel" hidden></section>');
  const toggle=document.querySelector('#notification-toggle'),panel=document.querySelector('#notification-panel');
  const load=async()=>{try{const rows=await req('/notifications');const unread=rows.filter(x=>!x.isRead).length;toggle.querySelector('span').textContent=unread;panel.innerHTML=`<div><b>Thông báo</b>${unread?'<button id="read-all" class="mini">Đã đọc tất cả</button>':''}</div>${rows.map(x=>`<article class="${x.isRead?'':'unread'}" data-notification="${x.id}"><b>${esc(x.title)}</b><p>${esc(x.message)}</p><small>${new Date(x.createdAt).toLocaleString('vi-VN')}</small></article>`).join('')||'<p class="muted">Chưa có thông báo.</p>'}`;panel.querySelectorAll('[data-notification]').forEach(item=>item.onclick=async()=>{try{await req(`/notifications/${item.dataset.notification}/read`,{method:'PUT'});if(item.querySelector('b')?.textContent.includes('học liệu')){view='materials';render()}else load()}catch(error){note(error.message,true)}});const all=panel.querySelector('#read-all');if(all)all.onclick=async()=>{await req('/notifications/read-all',{method:'PUT'});load()}}catch{toggle.style.display='none'}};
  toggle.onclick=()=>{panel.hidden=!panel.hidden;if(!panel.hidden)load()};load();
};

tests=async()=>{
  const queue=await req('/ccd/reviews/queue');let page=1;
  shell(`<section class="page-title"><div><p class="breadcrumb">CCD / KIỂM THỬ VÀ NGHIỆM THU</p><h1>Hàng chờ kiểm thử</h1><p>Chọn học liệu để đánh giá checklist, lập phiếu lỗi và ra kết luận nghiệm thu.</p></div></section><section class="data-panel"><div class="data-panel-head"><div><h2>Học liệu cần xử lý</h2><p id="ccd-count"></p></div><div class="data-tools"><input id="ccd-search" placeholder="Tìm mã, tên học liệu, giảng viên"></div></div><div class="table-wrap"><table><thead><tr><th>Học liệu</th><th>Khoa / học phần</th><th>Giảng viên</th><th>Phiên bản</th><th>Trạng thái</th><th></th></tr></thead><tbody id="ccd-rows"></tbody></table></div><div id="ccd-pager"></div></section>`);
  const materialStatus=x=>['Nháp','Đã tải','Đang xử lý AI','Đã kiểm tra AI','Chờ nghiệm thu','Cần chỉnh sửa','Đã nghiệm thu','Lưu trữ'][x]||'Chưa xác định';
  const paint=()=>{const q=document.querySelector('#ccd-search').value.trim().toLowerCase(),rows=queue.filter(x=>!q||`${x.materialCode} ${x.materialTitle} ${x.lecturer} ${x.course}`.toLowerCase().includes(q)),size=10;page=Math.min(page,Math.max(1,Math.ceil(rows.length/size)));document.querySelector('#ccd-count').textContent=`${rows.length} lượt kiểm thử`;document.querySelector('#ccd-rows').innerHTML=rows.slice((page-1)*size,page*size).map(x=>`<tr><td><span class="code">${esc(x.materialCode)}</span><br><b>${esc(x.materialTitle)}</b></td><td>${esc(x.department)}<small>${esc(x.course)}</small></td><td>${esc(x.lecturer)}</td><td>v${x.versionNumber}<small>${esc(x.fileName)}</small></td><td><span class="status ${x.materialStatus===6?'active':x.materialStatus===5?'locked':''}">${materialStatus(x.materialStatus)}</span></td><td><button class="mini" data-review="${x.id}">Đánh giá</button></td></tr>`).join('')||'<tr><td colspan="6" class="empty">Chưa có học liệu trong hàng chờ.</td></tr>';tablePager(document.querySelector('#ccd-pager'),rows.length,page,p=>{page=p;paint()});document.querySelectorAll('[data-review]').forEach(b=>b.onclick=()=>review(b.dataset.review))};document.querySelector('#ccd-search').oninput=()=>{page=1;paint()};paint();
  async function review(id){const [detail,ai]=await Promise.all([req(`/ccd/reviews/${id}`),req(`/auto-tests/${id}/report`).catch(()=>null)]),reviewMap=new Map(detail.reviews.map(x=>[x.qualityCriterionId,x]));const aiPanel=ai?`<section class="ai-panel"><div><p class="breadcrumb">ĐÁNH GIÁ TỰ ĐỘNG</p><h2>Điểm chất lượng: <strong>${ai.overallScore}/100</strong></h2><p>Kỹ thuật ${ai.technicalScore} · Nội dung ${ai.contentScore} · Sư phạm ${ai.pedagogyScore} · OBE ${ai.obeScore}</p></div><div class="ai-findings">${ai.findings.map(f=>`<article><b>${esc(f.group)} · ${esc(f.level)}</b><span>${esc(f.problem)}</span><small>Hướng xử lý: ${esc(f.solution)}</small></article>`).join('')||'<p>Chưa phát hiện vấn đề tự động từ dữ liệu đã nộp.</p>'}</div></section>`:'';shell(`<section class="page-title"><div><p class="breadcrumb">CCD / CHECKLIST</p><h1>Đánh giá học liệu</h1><p>Lưu checklist trước, lập phiếu lỗi nếu có điểm cần chỉnh sửa, sau đó ra kết luận.</p></div><button id="back-queue" class="export-button">← Hàng chờ</button></section>${aiPanel}<section class="data-panel"><div class="data-panel-head"><div><h2>Checklist kiểm thử</h2><p>${detail.criteria.length} tiêu chí áp dụng</p></div></div><form id="checklist-form" class="checklist-form">${detail.criteria.map(c=>{const v=reviewMap.get(c.id);return`<article class="check-item"><div><span class="code">${esc(c.code)}</span><b>${esc(c.name)}</b><small>${esc(c.category)} · Trọng số ${c.weight}${c.isRequired?' · Bắt buộc':''}</small>${c.description?`<p>${esc(c.description)}</p>`:''}</div><input type="hidden" name="criterionId" value="${c.id}"><select name="outcome"><option value="Dat" ${v?.outcome==='Dat'?'selected':''}>Đạt</option><option value="CanChinhSua" ${v?.outcome==='CanChinhSua'?'selected':''}>Cần chỉnh sửa</option><option value="KhongApDung" ${v?.outcome==='KhongApDung'?'selected':''}>Không áp dụng</option></select><textarea name="note" placeholder="Nhận xét cho tiêu chí này">${esc(v?.note||'')}</textarea></article>`}).join('')}<button>Lưu checklist</button></form></section><section class="data-panel"><div class="data-panel-head"><div><h2>Phiếu lỗi</h2><p>Lỗi mở sẽ ngăn nghiệm thu học liệu.</p></div></div><form id="issue-form"><label>Tiêu đề lỗi<input name="title" required placeholder="VD: Chưa gắn CLO cho hoạt động đánh giá"></label><label>Nhóm lỗi<select name="category"><option>Kỹ thuật</option><option>Nội dung</option><option>Sư phạm</option><option>OBE</option></select></label><label>Mức độ<select name="severity"><option>Thấp</option><option selected>TrungBinh</option><option>Cao</option><option>NghiêmTrọng</option></select></label><label>Hạn xử lý<input name="dueDate" type="date"></label><label class="wide">Mô tả lỗi<textarea name="description" required></textarea></label><label class="wide">Liên kết minh chứng (nếu có)<input name="evidenceUrl" type="url"></label><button>Lập phiếu lỗi</button></form><div class="issue-list">${detail.issues.map(x=>`<article><span class="status locked">${esc(x.severity)} · ${esc(x.status)}</span><b>${esc(x.title)}</b><p>${esc(x.description)}</p></article>`).join('')||'<p class="muted">Chưa có phiếu lỗi.</p>'}</div></section><section class="decision-panel"><h2>Kết luận kiểm thử</h2><textarea id="conclusion" placeholder="Nêu kết luận và kiến nghị cho giảng viên"></textarea><div><button id="need-revision" class="mini danger">Yêu cầu chỉnh sửa</button><button id="approve-review" class="export-button">Nghiệm thu học liệu</button></div></section>`);document.querySelector('#back-queue').onclick=tests;document.querySelector('#checklist-form').onsubmit=async e=>{e.preventDefault();const items=[...e.target.querySelectorAll('.check-item')].map(x=>({qualityCriterionId:x.querySelector('[name="criterionId"]').value,outcome:x.querySelector('[name="outcome"]').value,note:x.querySelector('[name="note"]').value||null}));try{await req(`/ccd/reviews/${id}/checklist`,{method:'PUT',body:JSON.stringify(items)});note('Đã lưu checklist.')}catch(err){note(err.message,true)}};document.querySelector('#issue-form').onsubmit=async e=>{e.preventDefault();const body=Object.fromEntries(new FormData(e.target));body.dueDate=body.dueDate||null;try{await req(`/ccd/reviews/${id}/issues`,{method:'POST',body:JSON.stringify(body)});review(id)}catch(err){note(err.message,true)}};const decide=async decision=>{try{await req(`/ccd/reviews/${id}/decision`,{method:'PUT',body:JSON.stringify({decision,conclusion:document.querySelector('#conclusion').value||null})});tests()}catch(err){note(err.message,true)}};document.querySelector('#need-revision').onclick=()=>decide('NeedRevision');document.querySelector('#approve-review').onclick=()=>decide('Approved');}
};
